char * get_string ( int eos ) { char buf [ DPISTRLEN + 1 ] ; char * s , * limit ; int c ; limit = buf + sizeof ( buf ) ; c = my_getch ( ) ; for ( s = buf ; ; c = my_getch ( ) ) { if ( c <= 0 || c == eos || ( eos == ' ' && c == '\t' ) ) { * s = 0 ; break ; } if ( c == '\n' ) { * s = 0 ; my_ungetch ( c ) ; break ; } else { * s ++ = c ; if ( s >= limit ) { return NULL ; } } } return strdup ( buf ) ; } 